--
-- Name: gift_vouchers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.gift_vouchers (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    code text NOT NULL,
    amount numeric(10,2) NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    used_at timestamp with time zone,
    used_by_order_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    discount_type text DEFAULT 'fixed'::text NOT NULL,
    CONSTRAINT gift_vouchers_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT gift_vouchers_discount_type_check CHECK ((discount_type = ANY (ARRAY['fixed'::text, 'percent'::text])))
);


--
-- Name: COLUMN gift_vouchers.discount_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.gift_vouchers.discount_type IS 'fixed = amount is a flat LKR discount; percent = amount is a percentage of (subtotal + delivery).';


