--
-- Name: ops_recipe_ingredients; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ops_recipe_ingredients (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    recipe_id uuid NOT NULL,
    name text NOT NULL,
    cost numeric(10,2) DEFAULT 0 NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL
);


--
-- Name: ops_recipes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ops_recipes (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    flavor text NOT NULL,
    per_piece_cost numeric(10,2) DEFAULT 0 NOT NULL,
    selling_price numeric(10,2) DEFAULT 0 NOT NULL,
    batch_pcs integer DEFAULT 20 NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: ops_sales; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ops_sales (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    channel text DEFAULT 'b2b'::text NOT NULL,
    sale_date date NOT NULL,
    flavor text,
    customer text,
    ref text,
    qty integer DEFAULT 0 NOT NULL,
    unit_price numeric(10,2) DEFAULT 0 NOT NULL,
    amount numeric(12,2) GENERATED ALWAYS AS (((qty)::numeric * unit_price)) STORED,
    discount numeric(10,2) DEFAULT 0 NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ops_sales_channel_check CHECK ((channel = ANY (ARRAY['b2b'::text, 'b2c'::text])))
);


--
-- Name: ops_shares; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ops_shares (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    holder text NOT NULL,
    share_pct numeric(6,4) DEFAULT 0 NOT NULL,
    earned numeric(12,2) DEFAULT 0 NOT NULL,
    paid numeric(12,2) DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: order_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.order_items (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    order_id uuid NOT NULL,
    product_id uuid,
    product_name text NOT NULL,
    package_id text,
    package_label text NOT NULL,
    piece_count integer NOT NULL,
    box_qty integer DEFAULT 1 NOT NULL,
    unit_price numeric(10,2) NOT NULL,
    unit_cost numeric(10,2),
    addons jsonb DEFAULT '[]'::jsonb NOT NULL,
    line_total numeric(10,2) NOT NULL,
    CONSTRAINT order_items_box_qty_check CHECK ((box_qty >= 1))
);


--
-- Name: orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.orders (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    order_no integer NOT NULL,
    status public.order_status DEFAULT 'pending'::public.order_status NOT NULL,
    customer_name text NOT NULL,
    phone text NOT NULL,
    address text,
    delivery_date date,
    note text,
    subtotal numeric(10,2) NOT NULL,
    delivery_fee numeric(10,2) NOT NULL,
    total numeric(10,2) NOT NULL,
    total_pieces integer NOT NULL,
    source text DEFAULT 'web'::text NOT NULL,
    inquiry_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    email text,
    alt_phone text,
    voucher_code text,
    voucher_discount numeric(10,2) DEFAULT 0 NOT NULL,
    is_gift boolean DEFAULT false NOT NULL,
    recipient_name text,
    recipient_phone text,
    payment_method text,
    payment_status text DEFAULT 'unpaid'::text NOT NULL,
    payment_ref text,
    slip_url text,
    delivery_slot text,
    CONSTRAINT orders_delivery_slot_check CHECK (((delivery_slot IS NULL) OR (delivery_slot = ANY (ARRAY['10-11'::text, '16-18'::text])))),
    CONSTRAINT orders_payment_method_check CHECK ((payment_method = ANY (ARRAY['bank_transfer'::text, 'card'::text]))),
    CONSTRAINT orders_payment_status_check CHECK ((payment_status = ANY (ARRAY['unpaid'::text, 'awaiting_verification'::text, 'paid'::text, 'failed'::text])))
);


--
-- Name: COLUMN orders.email; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.email IS 'Customer email captured at checkout (required at the app layer; nullable here for legacy/inquiry-converted rows).';


--
-- Name: COLUMN orders.alt_phone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orders.alt_phone IS 'Optional secondary contact number captured at checkout.';


--
-- Name: orders_order_no_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.orders_order_no_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: orders_order_no_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.orders_order_no_seq OWNED BY public.orders.order_no;


--
-- Name: packages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.packages (
    id text NOT NULL,
    label text NOT NULL,
    piece_count integer NOT NULL,
    is_slab boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    letter_max_chars integer DEFAULT 0 NOT NULL,
    CONSTRAINT packages_piece_count_check CHECK ((piece_count > 0))
);


--
-- Name: COLUMN packages.letter_max_chars; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.packages.letter_max_chars IS 'Max characters per topper line (3 lines, spec unchanged) for this package. 0 = no topper offered.';


--
-- Name: product_package_availability; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.product_package_availability (
    product_id uuid NOT NULL,
    package_id text NOT NULL,
    is_available boolean DEFAULT true NOT NULL
);


--
-- Name: TABLE product_package_availability; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.product_package_availability IS 'Per product×package availability overrides. No row = available. A row exists only when admin has hidden that package for the product (is_available=false).';


--
-- Name: product_package_stock; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.product_package_stock (
    product_id uuid NOT NULL,
    package_id text NOT NULL,
    in_stock boolean DEFAULT false NOT NULL
);


--
-- Name: TABLE product_package_stock; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.product_package_stock IS 'Per product×package sold-out overrides. No row = in stock. A row exists only when admin has explicitly marked that combo (almost always to mark it OUT of stock — in_stock=false); the table is not meant to hold one row per combo.';


--
-- Name: products; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.products (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    category_id uuid,
    name text NOT NULL,
    slug text NOT NULL,
    description text,
    price_per_piece numeric(10,2) NOT NULL,
    image_url text,
    is_visible boolean DEFAULT true NOT NULL,
    in_stock boolean DEFAULT true NOT NULL,
    stock_qty integer,
    is_slab_available boolean DEFAULT false NOT NULL,
    allows_letter_topper boolean DEFAULT false NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    media jsonb DEFAULT '[]'::jsonb NOT NULL,
    is_slab_15_available boolean DEFAULT false NOT NULL,
    is_hot_pick boolean DEFAULT false NOT NULL,
    is_corporate boolean DEFAULT false NOT NULL,
    is_slab_product boolean DEFAULT false NOT NULL,
    flavors jsonb DEFAULT '[]'::jsonb NOT NULL,
    slab_letter_max_chars integer DEFAULT 7 NOT NULL,
    CONSTRAINT products_price_per_piece_check CHECK ((price_per_piece >= (0)::numeric)),
    CONSTRAINT products_slab_letter_max_chars_check CHECK (((slab_letter_max_chars >= 0) AND (slab_letter_max_chars <= 20)))
);


--
-- Name: COLUMN products.is_slab_available; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.products.is_slab_available IS 'Can be ordered as the 12pc Brownie Slab (slab-12). Independent of is_slab_15_available.';


--
-- Name: COLUMN products.media; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.products.media IS 'Ordered gallery: [{"url": "...", "type": "image"|"video"}, ...]. media[0] is the cover, mirrored into image_url.';


--
-- Name: COLUMN products.is_slab_15_available; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.products.is_slab_15_available IS 'Can be ordered as the 15pc Brownie Slab (slab-15). Independent of is_slab_available.';


--
-- Name: COLUMN products.is_hot_pick; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.products.is_hot_pick IS 'Featured on the homepage Hot Picks section (below the hero). Admin-toggled.';


--
-- Name: COLUMN products.is_slab_product; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.products.is_slab_product IS 'Standalone Brownie Slab product — priced per product via `flavors`, flavour selector on the PDP.';


--
-- Name: COLUMN products.flavors; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.products.flavors IS 'Slab flavours: JSONB array of { "name": text, "price": number }. Empty for non-slab products.';


--
-- Name: COLUMN products.slab_letter_max_chars; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.products.slab_letter_max_chars IS 'Letter-topper characters allowed PER LINE on a standalone slab product (is_slab_product = true). The number of lines is fixed at 3 (TOPPER_LINES). Ignored for package-based products, which read packages.letter_max_chars. 0 disables the topper for this slab.';


--
