-- ============================================================================
-- STORAGE — buckets and their policies
--
-- Lives in the `storage` schema, which a public-schema dump does not cover, so
-- these are carried over verbatim from migrations 026/027 and storage-setup.sql.
--
-- Reminder: this creates the buckets and their access rules, NOT their
-- contents. Product images and bank slips must be copied across separately or
-- images will 404 on the storefront.
-- ============================================================================

-- product-images (PUBLIC): admin-uploaded product gallery media.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'product-images', 'product-images', true,
  52428800, -- 50 MB per file — comfortably covers a short product video
  array['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','video/quicktime']
)
on conflict (id) do update set
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "public read product-images" on storage.objects;
create policy "public read product-images"
  on storage.objects for select
  using (bucket_id = 'product-images');

drop policy if exists "admin write product-images" on storage.objects;
create policy "admin write product-images"
  on storage.objects for all
  using (bucket_id = 'product-images' and auth.role() = 'authenticated')
  with check (bucket_id = 'product-images' and auth.role() = 'authenticated');

-- bank-slips (PRIVATE): customer payment slips. Anyone may upload at checkout;
-- only signed-in staff may read, and only via short-lived signed URLs.
insert into storage.buckets (id, name, public)
values ('bank-slips', 'bank-slips', false)
on conflict (id) do nothing;

drop policy if exists "bank_slips_anon_insert" on storage.objects;
create policy "bank_slips_anon_insert" on storage.objects
  for insert to anon, authenticated
  with check (bucket_id = 'bank-slips');

drop policy if exists "bank_slips_admin_read" on storage.objects;
create policy "bank_slips_admin_read" on storage.objects
  for select to authenticated
  using (bucket_id = 'bank-slips');


